// A minimal PDF writer for the eval fixtures, so every fixture document is
// generated by committed code with no dependency and can be regenerated
// byte for byte (tests/unit/fixtures.test.ts checks the committed files
// against it).
//
// PDF 1.4, one uncompressed content stream per page, the standard Helvetica
// and Helvetica-Bold fonts (not embedded) with WinAnsiEncoding, US Letter
// pages. It draws text at a position with a size and a fill colour (so
// white-on-white and 2pt text are possible, which is what the injection
// fixtures need), straight lines and filled rectangles. Nothing in the
// output depends on the clock or the environment: no /CreationDate, no /ID.

export type Rgb = readonly [number, number, number];

export type PdfText = {
  kind: "text";
  x: number;
  y: number;
  text: string;
  size?: number;
  bold?: boolean;
  color?: Rgb;
  // "right": x is where the text ends (amount columns)
  align?: "left" | "right";
};

export type PdfLine = { kind: "line"; x1: number; y1: number; x2: number; y2: number; width?: number; color?: Rgb };

export type PdfRect = { kind: "rect"; x: number; y: number; width: number; height: number; color: Rgb };

export type PdfItem = PdfText | PdfLine | PdfRect;

export type PdfPage = readonly PdfItem[];

export const PAGE_WIDTH = 612;
export const PAGE_HEIGHT = 792;

export const BLACK: Rgb = [0, 0, 0];
export const WHITE: Rgb = [1, 1, 1];

// WinAnsiEncoding: Latin-1 for 0xA0-0xFF, ASCII below 0x80, and these
// characters in 0x80-0x9F. Anything else is a fixture authoring error.
const WIN_ANSI_EXTRAS: Record<string, number> = {
  "\u20ac": 0x80, // euro sign
  "\u201a": 0x82, // single low quote
  "\u201e": 0x84, // double low quote
  "\u2026": 0x85, // ellipsis
  "\u2018": 0x91, // left single quote
  "\u2019": 0x92, // right single quote
  "\u201c": 0x93, // left double quote
  "\u201d": 0x94, // right double quote
  "\u2022": 0x95, // bullet
  "\u2013": 0x96, // en dash
  "\u2014": 0x97, // em dash
  "\u2122": 0x99, // trade mark
};

function encodeWinAnsi(text: string): number[] {
  const bytes: number[] = [];
  for (const char of text) {
    const code = char.codePointAt(0) ?? 0;
    if ((code >= 0x20 && code < 0x7f) || (code >= 0xa0 && code <= 0xff)) bytes.push(code);
    else if (char in WIN_ANSI_EXTRAS) bytes.push(WIN_ANSI_EXTRAS[char]);
    else throw new Error(`character U+${code.toString(16).padStart(4, "0")} has no WinAnsi encoding`);
  }
  return bytes;
}

// A PDF string literal: backslash, parentheses escaped; bytes as latin1.
function pdfString(text: string): string {
  let out = "(";
  for (const byte of encodeWinAnsi(text)) {
    const char = String.fromCharCode(byte);
    out += char === "\\" || char === "(" || char === ")" ? `\\${char}` : char;
  }
  return `${out})`;
}

// Helvetica advance widths (per 1000 units of font size) from the standard
// AFM, for right-aligning amounts. Characters outside the table use the
// average width; only layout depends on it, not correctness.
const HELVETICA_WIDTHS: Record<string, number> = {
  " ": 278, "!": 278, "#": 556, $: 556, "%": 889, "&": 667, "'": 191, "(": 333, ")": 333, "*": 389, "+": 584,
  ",": 278, "-": 333, ".": 278, "/": 278, ":": 278, ";": 278, "=": 584, "?": 556, "@": 1015, "\u20ac": 556,
  A: 667, B: 667, C: 722, D: 722, E: 667, F: 611, G: 778, H: 722, I: 278, J: 500, K: 667, L: 556, M: 833,
  N: 722, O: 778, P: 667, Q: 778, R: 722, S: 667, T: 611, U: 722, V: 667, W: 944, X: 667, Y: 667, Z: 611,
  a: 556, b: 556, c: 500, d: 556, e: 556, f: 278, g: 556, h: 556, i: 222, j: 222, k: 500, l: 222, m: 833,
  n: 556, o: 556, p: 556, q: 556, r: 333, s: 500, t: 278, u: 556, v: 500, w: 722, x: 500, y: 500, z: 500,
};

export function textWidth(text: string, size: number): number {
  let units = 0;
  for (const char of text) units += /\d/.test(char) ? 556 : (HELVETICA_WIDTHS[char] ?? 556);
  return (units * size) / 1000;
}

// Two decimals at most, no exponent, no trailing zeros: stable output.
function num(value: number): string {
  if (!Number.isFinite(value)) throw new Error(`not a finite number: ${value}`);
  return String(Math.round(value * 100) / 100);
}

function rgb(color: Rgb): string {
  return color.map(num).join(" ");
}

function contentStream(page: PdfPage): string {
  const ops: string[] = [];
  for (const item of page) {
    if (item.kind === "rect") {
      ops.push(`${rgb(item.color)} rg ${num(item.x)} ${num(item.y)} ${num(item.width)} ${num(item.height)} re f`);
    } else if (item.kind === "line") {
      ops.push(
        `${num(item.width ?? 0.5)} w ${rgb(item.color ?? BLACK)} RG ${num(item.x1)} ${num(item.y1)} m ${num(item.x2)} ${num(item.y2)} l S`,
      );
    } else {
      const size = item.size ?? 10;
      const x = item.align === "right" ? item.x - textWidth(item.text, size) : item.x;
      ops.push(
        `BT /${item.bold ? "F2" : "F1"} ${num(size)} Tf ${rgb(item.color ?? BLACK)} rg ${num(x)} ${num(item.y)} Td ${pdfString(item.text)} Tj ET`,
      );
    }
  }
  return ops.join("\n") + "\n";
}

function latin1(text: string): Uint8Array {
  const bytes = new Uint8Array(text.length);
  for (let i = 0; i < text.length; i += 1) {
    const code = text.charCodeAt(i);
    if (code > 0xff) throw new Error("internal: non-latin1 character in PDF body");
    bytes[i] = code;
  }
  return bytes;
}

export function buildPdf(pages: readonly PdfPage[]): Uint8Array {
  if (pages.length === 0) throw new Error("a PDF needs at least one page");

  // 1 catalog, 2 page tree, 3 Helvetica, 4 Helvetica-Bold, then a page
  // object and its content stream per page
  const objects: string[] = [];
  const pageIds = pages.map((_, i) => 5 + i * 2);
  objects.push("<< /Type /Catalog /Pages 2 0 R >>");
  objects.push(`<< /Type /Pages /Kids [${pageIds.map((id) => `${id} 0 R`).join(" ")}] /Count ${pages.length} >>`);
  objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
  objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");
  pages.forEach((page, i) => {
    const contentId = pageIds[i] + 1;
    objects.push(
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_WIDTH} ${PAGE_HEIGHT}] ` +
        `/Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${contentId} 0 R >>`,
    );
    const stream = contentStream(page);
    // every character in the stream is one byte (latin1), so length is bytes
    objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}endstream`);
  });

  // The header's second line is a comment of four bytes above 0x7F, which
  // tells tools the file is binary.
  let body = "%PDF-1.4\n%\u00e2\u00e3\u00cf\u00d3\n";
  const offsets: number[] = [];
  objects.forEach((object, i) => {
    offsets.push(body.length);
    body += `${i + 1} 0 obj\n${object}\nendobj\n`;
  });

  const xrefOffset = body.length;
  // each entry is exactly 20 bytes: 10-digit offset, space, 5-digit
  // generation, space, n or f, space, newline
  const entries = ["0000000000 65535 f \n", ...offsets.map((o) => `${String(o).padStart(10, "0")} 00000 n \n`)];
  body += `xref\n0 ${objects.length + 1}\n${entries.join("")}`;
  body += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`;
  return latin1(body);
}
